 * @returns A loader plus run-level cleanup operation.
 * @public
 */
export declare const createGeoSpecNativeModelLoader: (defaults: CreateGeoSpecNativeModelLoaderOptions) => ManagedGeoSpecNativeModelLoader;
//#endregion

